import * as React from "react"
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion"
import { Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import "./accordion.css"

type AccordionValue = (string | number | null)[]

type AccordionProps = Omit<
  React.ComponentProps<typeof AccordionPrimitive.Root>,
  "value" | "defaultValue" | "onValueChange"
> & {
  type?: "single" | "multiple"
  collapsible?: boolean
  value?: string | string[] | AccordionValue
  defaultValue?: string | string[] | AccordionValue
  onValueChange?: (value: string | string[]) => void
}

function Accordion({
  className,
  type = "multiple",
  collapsible = true,
  value,
  defaultValue,
  onValueChange,
  ...props
}: AccordionProps) {
  const isSingle = type === "single"

  const toArray = (v: string | string[] | AccordionValue | undefined): AccordionValue => {
    if (v === undefined) return []
    if (Array.isArray(v)) return v as AccordionValue
    return [v]
  }

  const fromArray = (v: AccordionValue): string | string[] => {
    const filtered = v.filter((x): x is string | number => x !== null).map(String)
    return isSingle ? filtered[0] ?? "" : filtered
  }

  const [internalValue, setInternalValue] = React.useState<AccordionValue>(() =>
    defaultValue !== undefined ? toArray(defaultValue) : []
  )
  const isControlled = value !== undefined
  const currentValue = isControlled ? toArray(value) : internalValue

  const handleChange = (next: AccordionValue) => {
    let constrained: AccordionValue = next
    if (isSingle) {
      const last = next.slice(-1)
      // type=single: only one open at a time
      // collapsible=false: prevent closing the only open item
      if (!collapsible && last.length === 0 && currentValue.length > 0) {
        return
      }
      constrained = last
    }
    if (!isControlled) setInternalValue(constrained)
    onValueChange?.(fromArray(constrained))
  }

  return (
    <AccordionPrimitive.Root
      data-slot="accordion"
      className={cn("flex flex-col gap-[var(--layout-gap-sm)]", className)}
      value={currentValue}
      onValueChange={handleChange}
      {...props}
    />
  )
}

function AccordionItem({
  className,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Item>) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn(
        "accordion-item rounded-[var(--layout-radius-md)] overflow-hidden",
        className
      )}
      {...props}
    />
  )
}

function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Trigger>) {
  return (
    <AccordionPrimitive.Header data-slot="accordion-header" className="flex">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "accordion-trigger flex flex-1 items-center justify-between min-h-[var(--layout-size-lg)] px-[var(--layout-padding-lg)] py-[var(--layout-padding-md)] text-content-body font-accent cursor-pointer focus-visible:outline-none",
          className
        )}
        {...props}
      >
        <span>{children}</span>
        <span className="accordion-icon shrink-0 [&_svg]:h-[var(--layout-size-xs)] [&_svg]:w-[var(--layout-size-xs)]">
          <Plus />
        </span>
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  )
}

function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Panel>) {
  return (
    <AccordionPrimitive.Panel
      data-slot="accordion-content"
      className={cn("accordion-content overflow-hidden", className)}
      {...props}
    >
      <div className="accordion-content-inner px-[var(--layout-padding-lg)] pb-[var(--layout-padding-lg)] text-content-note">
        {children}
      </div>
    </AccordionPrimitive.Panel>
  )
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent }

/* ================================================================
 * ACCORDION — Item, Trigger, Icon & Content Styles
 * Structure (flex, padding, radius, gap) lives in accordion.tsx.
 * Theming (colors, borders, transitions, animation) lives here.
 * ================================================================ */

/* --------------------------------
 * Item — card background
 * -------------------------------- */
.accordion-item {
  background-color: var(--background-neutral-faint-default);
}

/* --------------------------------
 * Trigger — text color + states
 * -------------------------------- */
.accordion-trigger {
  color: var(--text-base-strong);
}

.accordion-trigger:hover {
  color: var(--text-base-bolder);
}

.accordion-trigger[data-disabled] {
  color: var(--text-disabled);
  cursor: default;
  pointer-events: none;
}

/* --------------------------------
 * Trigger — focus ring
 * -------------------------------- */
.accordion-trigger:focus-visible {
  box-shadow: 0 0 0 2px var(--background-base), 0 0 0 4px var(--border-selected);
}

/* --------------------------------
 * Icon — Plus rotates 45° to become × when open
 * -------------------------------- */
.accordion-icon {
  color: var(--text-base-moderate);
  transition: transform 250ms ease;
}

.accordion-trigger[data-panel-open] .accordion-icon {
  transform: rotate(45deg);
}

.accordion-trigger[data-disabled] .accordion-icon {
  color: var(--text-disabled);
}

/* --------------------------------
 * Content — height animation
 * Uses Base UI CSS variable --accordion-panel-height
 * -------------------------------- */
.accordion-content[data-open] {
  animation: accordion-expand 250ms ease;
}

.accordion-content[data-ending-style] {
  animation: accordion-collapse 250ms ease;
}

@keyframes accordion-expand {
  from {
    height: 0;
  }
  to {
    height: var(--accordion-panel-height);
  }
}

@keyframes accordion-collapse {
  from {
    height: var(--accordion-panel-height);
  }
  to {
    height: 0;
  }
}

/* --------------------------------
 * Content — text color
 * -------------------------------- */
.accordion-content-inner {
  color: var(--text-base-moderate);
}

/* --------------------------------
 * Reduced motion — slow to 400ms (project pattern)
 * -------------------------------- */
@media (prefers-reduced-motion: reduce) {
  .accordion-content[data-open],
  .accordion-content[data-ending-style] {
    animation-duration: 400ms;
    animation-timing-function: linear;
  }

  .accordion-icon {
    transition-duration: 400ms;
  }
}

/* --------------------------------
 * Forced colors (Windows High Contrast)
 * -------------------------------- */
@media (forced-colors: active) {
  .accordion-item {
    border: var(--layout-border-thin) solid ButtonText;
  }

  .accordion-trigger {
    color: ButtonText;
  }

  .accordion-trigger:focus-visible {
    outline: 2px solid ButtonText;
    box-shadow: none;
  }

  .accordion-icon {
    color: ButtonText;
  }
}
